insert into public.servicios (id, name_es, name_en, description_es, description_en, "order") values ('ecommerce', 'Quiero vender mis productos por internet', 'I want to sell my products online', 'Tienda online completa: catálogo, carrito, pagos y panel para que manejes tus productos tú mismo.', 'Full online store: catalog, cart, payments and a panel so you manage your own products.', 1) on conflict (id) do nothing;
insert into public.servicios (id, name_es, name_en, description_es, description_en, "order") values ('seo-web', 'Quiero que mi negocio aparezca en Google y lo encuentren', 'I want my business to show up on Google', 'Página profesional optimizada para que tus clientes te encuentren cuando busquen lo que ofreces.', 'Professional page optimized so your customers find you when they search for what you offer.', 2) on conflict (id) do nothing;
insert into public.servicios (id, name_es, name_en, description_es, description_en, "order") values ('portfolio', 'Quiero mostrar mi trabajo o mi carrera', 'I want to showcase my work or career', 'Portafolio o CV digital que transmite quién eres y qué has logrado, de forma profesional.', 'Portfolio or digital resume that shows who you are and what you have achieved, professionally.', 3) on conflict (id) do nothing;
insert into public.servicios (id, name_es, name_en, description_es, description_en, "order") values ('landing', 'Quiero promocionar algo puntual', 'I want to promote something specific', 'Landing page enfocada en convertir visitantes en clientes para un producto, servicio o evento.', 'Landing page focused on converting visitors into customers for a product, service, or event.', 4) on conflict (id) do nothing;
insert into public.servicios (id, name_es, name_en, description_es, description_en, "order") values ('custom', 'No estoy seguro / quiero que me asesores', 'I''m not sure / I''d like some advice', 'Cuéntame tu idea y te oriento hacia la solución más adecuada para tu negocio.', 'Tell me your idea and I''ll guide you toward the best solution for your business.', 5) on conflict (id) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('tienda-artesanias-quito', 'demo', 'ecommerce', true, 'Artesanías del Ecuador', 'Ecuador Crafts', 'Tienda online para un taller artesanal, con catálogo, pagos y gestión de inventario propia.', 'Online store for an artisan workshop, with catalog, payments and self-managed inventory.', 'Que el taller pudiera vender fuera de Instagram y llegar a clientes que no usan redes sociales.', 'Get the workshop selling beyond Instagram and reach customers who don''t use social media.', 'Un taller artesanal en Quito vendía solo por Instagram, perdiendo clientes que no usaban redes sociales.', 'An artisan workshop in Quito was selling only through Instagram, missing customers who don''t use social media.', 'Le hice una tienda online donde los clientes pueden ver el catálogo completo, pagar con tarjeta y el dueño maneja su inventario sin depender de nadie.', 'I built them an online store where customers can browse the full catalog, pay by card, and the owner manages their inventory independently.', 'Necesitaba un checkout simple para clientes poco familiarizados con compras online, y sincronizar el inventario en tiempo real para evitar vender piezas artesanales de stock único que ya no existían.', 'The checkout had to stay simple for customers unfamiliar with online shopping, and inventory needed real-time sync to avoid selling one-of-a-kind pieces that were already gone.', 'El taller ahora vende directamente desde su web, sin depender de que un cliente le escriba por Instagram, y controla su inventario sin hojas de cálculo.', 'The workshop now sells directly from its website instead of relying on Instagram DMs, and manages inventory without spreadsheets.', '[{"title_es":"Catálogo de productos","title_en":"Product catalog","benefit_es":"el cliente ve todo el catálogo con fotos y precios sin tener que pedirlo por mensaje.","benefit_en":"customers browse the full catalog with photos and prices without messaging to ask."},{"title_es":"Pago con tarjeta (Stripe)","title_en":"Card payments (Stripe)","benefit_es":"el cliente compra y paga en el momento, sin transferencias ni esperar confirmación manual.","benefit_en":"customers buy and pay instantly, no bank transfers or waiting for manual confirmation."},{"title_es":"Panel de inventario","title_en":"Inventory dashboard","benefit_es":"el dueño actualiza el stock de cada pieza artesanal él mismo, sin depender de un programador.","benefit_en":"the owner updates stock for each piece himself, without needing a developer."}]'::jsonb, ARRAY['Next.js', 'Supabase', 'Stripe', 'TypeScript']::text[], null) on conflict (slug) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('restaurante-la-ronda', 'demo', 'seo-web', true, 'Restaurante La Ronda', 'La Ronda Restaurant', 'Sitio web optimizado para SEO local de un restaurante del centro histórico de Quito.', 'Local-SEO-optimized website for a restaurant in Quito''s historic center.', 'Que el restaurante apareciera en Google para quienes buscan dónde comer en el centro, sin depender solo del boca a boca.', 'Get the restaurant showing up on Google for people searching where to eat downtown, instead of relying only on word of mouth.', 'Un restaurante del centro histórico no aparecía en Google y sus clientes llegaban solo por recomendación boca a boca.', 'A historic center restaurant wasn''t showing up on Google and customers only found it through word of mouth.', 'Le construí una página optimizada para buscadores con menú, fotos, ubicación y reseñas.', 'I built them a search-optimized page with menu, photos, location and reviews.', 'El reto fue optimizar la velocidad de carga y la estructura SEO sin perder el diseño visual que el dueño quería, y configurar bien Google Business para que ambos canales trabajaran juntos.', 'The challenge was optimizing load speed and SEO structure without losing the visual design the owner wanted, and configuring Google Business correctly so both channels worked together.', 'En tres meses empezó a aparecer en los primeros resultados locales de Google.', 'Within three months it started appearing in top local Google results.', '[{"title_es":"Menú digital actualizable","title_en":"Editable digital menu","benefit_es":"el dueño cambia platos y precios él mismo, sin depender de reimprimir cartas físicas.","benefit_en":"the owner updates dishes and prices himself, without reprinting physical menus."},{"title_es":"SEO local","title_en":"Local SEO","benefit_es":"el restaurante aparece cuando alguien busca ''dónde comer'' cerca de esa zona, no solo por su nombre.","benefit_en":"the restaurant shows up when someone searches ''where to eat'' nearby, not just by name."},{"title_es":"Galería de fotos y reseñas","title_en":"Photo gallery and reviews","benefit_es":"el cliente decide visitar el lugar antes de llegar, viendo fotos reales y opiniones.","benefit_en":"customers decide to visit before arriving, seeing real photos and reviews."}]'::jsonb, ARRAY['Next.js', 'Tailwind CSS', 'TypeScript']::text[], null) on conflict (slug) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('portafolio-fotografa', 'demo', 'portfolio', true, 'Daniela López — Fotógrafa', 'Daniela López — Photographer', 'Portafolio visual para una fotógrafa profesional, con galerías por categoría y carga rápida de imágenes.', 'Visual portfolio for a professional photographer, with category galleries and fast image loading.', 'Que pudiera mostrar su trabajo de forma profesional a clientes corporativos, más allá de Instagram.', 'Let her present her work professionally to corporate clients, beyond Instagram.', 'Una fotógrafa profesional compartía su trabajo solo en Instagram, sin poder presentar un portafolio profesional a clientes corporativos.', 'A professional photographer was sharing work only on Instagram, unable to present a professional portfolio to corporate clients.', 'Le diseñé un portafolio visual con galerías por categoría, página de contacto y carga ultra-rápida de imágenes para que nunca pierda a un cliente por lentitud.', 'I designed a visual portfolio with galleries by category, a contact page and ultra-fast image loading so she never loses a client due to slow load times.', 'El reto fue optimizar decenas de imágenes en alta resolución sin sacrificar calidad visual, manteniendo tiempos de carga rápidos incluso en conexiones móviles.', 'The challenge was optimizing dozens of high-resolution images without sacrificing visual quality, keeping load times fast even on mobile connections.', 'Ahora envía un solo link a marcas y agencias en vez de compartir carpetas de Drive o su perfil de Instagram.', 'She now sends a single link to brands and agencies instead of sharing Drive folders or her Instagram profile.', '[{"title_es":"Galerías por categoría","title_en":"Category galleries","benefit_es":"el cliente encuentra rápido el tipo de trabajo que busca (bodas, retratos, eventos) sin scrollear todo.","benefit_en":"clients quickly find the type of work they need (weddings, portraits, events) without scrolling everything."},{"title_es":"Carga rápida de imágenes","title_en":"Fast image loading","benefit_es":"las fotos se ven nítidas y cargan al instante, incluso en celular.","benefit_en":"photos look sharp and load instantly, even on mobile."},{"title_es":"Formulario de contacto directo","title_en":"Direct contact form","benefit_es":"un cliente interesado la contrata sin salir del sitio.","benefit_en":"an interested client can hire her without leaving the site."}]'::jsonb, ARRAY['Next.js', 'Framer Motion', 'Supabase Storage']::text[], null) on conflict (slug) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('landing-curso-online', 'demo', 'landing', false, 'Curso de Finanzas Personales', 'Personal Finance Course', 'Landing page de lanzamiento para un curso online de finanzas personales.', 'Launch landing page for an online personal finance course.', 'Convertir a personas interesadas en el curso en compradores, con una página enfocada 100% en la venta.', 'Turn people interested in the course into buyers, with a page focused entirely on conversion.', 'Un coach financiero lanzaba un curso pero no tenía una página convincente para convertir interesados en compradores.', 'A financial coach was launching a course but had no convincing page to convert interested people into buyers.', 'Le hice una landing page con testimonios, módulos del curso, contador de plazas y botón de compra directo.', 'I built a landing page with testimonials, course modules, a seat counter and a direct purchase button.', 'El reto fue generar urgencia real (cupos limitados) sin que se sintiera forzado, y conectar el botón de compra directo con la pasarela de pago sin fricciones.', 'The challenge was creating real urgency (limited spots) without it feeling forced, and connecting the direct purchase button to the payment gateway without friction.', 'Vendió el 80% de los cupos disponibles en la primera semana de lanzamiento.', 'They sold 80% of available spots in the first week after launch.', '[{"title_es":"Contador de plazas","title_en":"Seat counter","benefit_es":"el visitante ve cuántos cupos quedan y decide comprar antes de perder su lugar.","benefit_en":"visitors see how many spots are left and decide to buy before losing their seat."},{"title_es":"Testimonios en video","title_en":"Video testimonials","benefit_es":"quien duda del curso ve resultados de alumnos reales antes de pagar.","benefit_en":"someone unsure about the course sees real student results before paying."},{"title_es":"Compra directa","title_en":"Direct checkout","benefit_es":"paga en el momento sin salir del sitio ni escribir por WhatsApp para coordinar el pago.","benefit_en":"pays instantly without leaving the site or messaging on WhatsApp to arrange payment."}]'::jsonb, ARRAY['Next.js', 'Tailwind CSS', 'Stripe']::text[], null) on conflict (slug) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('app-gestion-inventarios', 'cliente', 'custom', false, 'Distribuidora El Sol', 'El Sol Distributors', 'App web a medida para reemplazar las hojas de cálculo de inventario de una distribuidora.', 'Custom web app to replace a distributor''s spreadsheet-based inventory.', 'Que la distribuidora dejara de perder el rastro de productos y de duplicar pedidos a proveedores por errores manuales.', 'Stop the distributor from losing track of products and duplicating supplier orders due to manual errors.', 'Una distribuidora local manejaba su inventario en hojas de cálculo, perdiendo el rastro de productos y generando pedidos duplicados a proveedores.', 'A local distributor was managing inventory in spreadsheets, losing track of products and generating duplicate supplier orders.', 'Les desarrollé una app web a medida con panel de control, alertas de stock bajo y generación automática de órdenes de compra.', 'I built a custom web app with a dashboard, low-stock alerts and automatic purchase order generation.', 'El mayor reto fue diseñar las alertas de stock bajo para que fueran útiles sin saturar al equipo de notificaciones, y migrar años de datos históricos desde hojas de cálculo sin perder información.', 'The biggest challenge was designing low-stock alerts that were useful without overwhelming the team with notifications, and migrating years of historical data from spreadsheets without losing information.', 'Redujeron los errores de inventario en un 90% y dejaron de generar pedidos duplicados a proveedores.', 'They reduced inventory errors by 90% and stopped generating duplicate supplier orders.', '[{"title_es":"Panel de control","title_en":"Dashboard","benefit_es":"el encargado ve de un vistazo qué productos están por agotarse, sin abrir ningún Excel.","benefit_en":"the manager sees at a glance which products are about to run out, without opening any spreadsheet."},{"title_es":"Alertas de stock bajo","title_en":"Low-stock alerts","benefit_es":"el sistema avisa antes de que un producto se agote, evitando ventas perdidas.","benefit_en":"the system warns before a product runs out, avoiding lost sales."},{"title_es":"Órdenes de compra automáticas","title_en":"Automatic purchase orders","benefit_es":"ya no se piden productos duplicados a proveedores por error humano.","benefit_en":"duplicate supplier orders from human error no longer happen."}]'::jsonb, ARRAY['React', 'Node.js', 'PostgreSQL', 'Tailwind CSS']::text[], null) on conflict (slug) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('sitio-corredora-propiedades', 'cliente', 'seo-web', false, 'Corredora de Propiedades MG', 'MG Real Estate', 'Rediseño de sitio web con SEO completo para una corredora de propiedades.', 'Full website redesign with complete SEO for a real estate agency.', 'Que el sitio volviera a aparecer en Google y generara consultas reales de compradores interesados.', 'Get the site showing up on Google again and generating real inquiries from interested buyers.', 'Una corredora de propiedades tenía un sitio web desactualizado que no aparecía en Google y no generaba leads.', 'A real estate agent had an outdated website that didn''t appear on Google and generated no leads.', 'Le rediseñé el sitio con listado de propiedades, filtros por zona/precio, formulario de contacto integrado y SEO completo.', 'I redesigned their site with property listings, filters by area/price, an integrated contact form and full SEO.', 'El reto fue reestructurar todo el SEO técnico de un sitio desactualizado (URLs, metadatos, velocidad) sin perder el poco tráfico que ya tenía durante la migración.', 'The challenge was restructuring all the technical SEO of an outdated site (URLs, metadata, speed) without losing the little traffic it already had during the migration.', 'En 2 meses triplicó las consultas de clientes interesados en propiedades.', 'Within 2 months, inquiries from interested buyers tripled.', '[{"title_es":"Listado con filtros","title_en":"Filterable listings","benefit_es":"el comprador filtra por zona y precio y encuentra propiedades que le interesan en segundos.","benefit_en":"buyers filter by area and price and find properties they''re interested in within seconds."},{"title_es":"Formulario de contacto integrado","title_en":"Integrated contact form","benefit_es":"un interesado deja sus datos directamente en la ficha de la propiedad, sin llamar.","benefit_en":"an interested buyer leaves their info directly on the listing page, without calling."},{"title_es":"SEO técnico completo","title_en":"Full technical SEO","benefit_es":"la corredora aparece en Google cuando alguien busca propiedades en su zona.","benefit_en":"the agency shows up on Google when someone searches for properties in their area."}]'::jsonb, ARRAY['Next.js', 'Tailwind CSS', 'TypeScript', 'Supabase']::text[], 'https://mg-propiedades.example.com') on conflict (slug) do nothing;
insert into public.proyectos (slug, category, service_id, featured, business_es, business_en, description_es, description_en, objective_es, objective_en, problem_es, problem_en, solution_es, solution_en, challenges_es, challenges_en, results_es, results_en, features, technologies, live_url) values ('landing-evento-tech', 'demo', 'landing', false, 'Conferencia TechQuito 2025', 'TechQuito 2025 Conference', 'Landing page de registro para una conferencia de tecnología en Quito.', 'Registration landing page for a tech conference in Quito.', 'Registrar asistentes y patrocinadores en menos de dos semanas, con un proceso de pago integrado.', 'Register attendees and sponsors in under two weeks, with an integrated payment process.', 'La organización de una conferencia tech necesitaba una landing para registrar asistentes y patrocinadores en menos de dos semanas.', 'A tech conference organization needed a landing page to register attendees and sponsors in under two weeks.', 'Construí una landing con contador regresivo, formulario de registro, grid de speakers y pasarela de pago.', 'I built a landing page with a countdown timer, registration form, speaker grid and payment gateway.', 'El reto fue construir y lanzar la página completa —incluyendo pagos— en menos de dos semanas, sin sacrificar el diseño ni la confiabilidad del checkout.', 'The challenge was building and launching the entire page —including payments— in under two weeks, without sacrificing design or checkout reliability.', 'Registraron más de 300 asistentes en los primeros 10 días desde el lanzamiento.', 'They registered over 300 attendees in the first 10 days after launch.', '[{"title_es":"Contador regresivo","title_en":"Countdown timer","benefit_es":"el visitante siente la urgencia de registrarse antes de que se acabe el tiempo.","benefit_en":"visitors feel the urgency to register before time runs out."},{"title_es":"Grid de speakers","title_en":"Speaker grid","benefit_es":"el asistente ve quién va a hablar antes de decidir comprar su entrada.","benefit_en":"attendees see who''s speaking before deciding to buy a ticket."},{"title_es":"Pasarela de pago integrada","title_en":"Integrated payment gateway","benefit_es":"compra su entrada al instante, sin transferencias ni coordinación manual.","benefit_en":"buys a ticket instantly, no bank transfers or manual coordination."}]'::jsonb, ARRAY['Next.js', 'Stripe', 'Tailwind CSS', 'TypeScript']::text[], null) on conflict (slug) do nothing;
